  /**
   * https://docs.taler.net/core/api-merchant.html#get-[-instances-$INSTANCE]-private-kyc
   */
  async getCurrentInstanceKycStatus(token, params = {}) {
    const url = new URL(`private/kyc`, this.baseUrl);
    if (params.wireHash) {
      url.searchParams.set("h_wire", params.wireHash);
    }
    if (params.exchangeURL) {
      url.searchParams.set("exchange_url", params.exchangeURL);
    }
    const headers = {};
    if (params.longpoll) {
      switch (params.longpoll.type) {
        case "state-enter":
          if (params.longpoll.status) {
            url.searchParams.set("lp_status", params.longpoll.status);
            url.searchParams.set("timeout_ms", String(params.longpoll.timeout));
          }
          break;
        case "state-exit":
          if (params.longpoll.status) {
            url.searchParams.set("lp_not_status", params.longpoll.status);
            url.searchParams.set("timeout_ms", String(params.longpoll.timeout));
          }
          break;
        case "state-change":
          if (params.longpoll.etag && params.longpoll.etag.trim()) {
            url.searchParams.set("lp_not_etag", params.longpoll.etag);
            headers["If-none-match"] = `"${params.longpoll.etag}"`;
            url.searchParams.set("timeout_ms", String(params.longpoll.timeout));
          }
          break;
        default:
          assertUnreachable(params.longpoll);
      }
    }
    if (token) {
      headers.Authorization = makeBearerTokenAuthHeader(token);
    }
    const cancellationToken = params.cancellationToken ?? this.cancellationToken;
    const resp = await this.httpLib.fetch(url.href, {
      method: "GET",
      headers,
      cancellationToken
    });
    const etag = resp.headers.get("etag")?.replace(/"/g, "");
    switch (resp.status) {
      case HttpStatusCode.Ok: {
        const f = await opSuccessFromHttp(resp, codecForAccountKycRedirects());
        return opFixedSuccess(resp, { etag, ...f.body });
      }
      case HttpStatusCode.NoContent:
        return opFixedSuccess(resp, { kyc_data: [], etag });
      case HttpStatusCode.NotModified:
        return opKnownFailureWithBody(resp, resp.status, { etag });
      case HttpStatusCode.Unauthorized:
        return opKnownHttpFailure(resp.status, resp);
      case HttpStatusCode.NotFound:
        return opKnownHttpFailure(resp.status, resp);
      case HttpStatusCode.ServiceUnavailable:
        return opKnownHttpFailure(resp.status, resp);
      case HttpStatusCode.GatewayTimeout:
        return opKnownHttpFailure(resp.status, resp);
      default:
        return opUnknownHttpFailure(resp);
    }
  }
