    const localIdent = num(counter?.next_ident);
    await this.run("INSERT INTO transaction_local_ids (transaction_id, transaction_type, local_ident) VALUES ($id, $type, $localIdent)", { id: transactionId, type: transactionType, localIdent });
    await this.run("UPDATE transaction_local_id_counters SET next_ident = next_ident + 1 WHERE transaction_type = $type", { type: transactionType });
