async function getWithdrawableDenoms(wex, exchangeBaseUrl, currency) {
  return await wex.runWalletDbTx(async (tx) => {
    return getWithdrawableDenomsTx(wex, tx, exchangeBaseUrl, currency);
  });
}
async function getWithdrawalMasterPub(tx, exchangeBaseUrl) {
  const det = await tx.getExchangeDetails(exchangeBaseUrl);
  checkDbInvariant(!!det, `no exchange details for ${exchangeBaseUrl}`);
  return det.masterPublicKey;
}
async function getWithdrawableDenomsTx(_wex, tx, exchangeBaseUrl, currency, maxAmount) {
  const dbNow = timestampProtocolToDb(TalerProtocolTimestamp.now());
  const acceptedMasterPub = (await tx.getExchange(exchangeBaseUrl))?.detailsPointer?.masterPublicKey;
  const allFamilies = (await tx.getDenominationFamiliesByExchange(exchangeBaseUrl)).filter((fam) => acceptedMasterPub == null || fam.familyParams.exchangeMasterPub === acceptedMasterPub);
  if (logger37.shouldLogTrace()) {
    const maxStr = maxAmount ? Amounts.stringify(maxAmount) : "<unknown>";
    logger37.trace(`getting withdrawable denoms for ${currency} / max=${maxStr} at ${exchangeBaseUrl}`);
    logger37.trace(`have ${allFamilies.length} families`);
  }
  const relevantDenoms = [];
  for (const fam of allFamilies) {
    const famCurrency = Amounts.currencyOf(fam.familyParams.value);
    if (famCurrency != currency) {
      logger37.warn(`unexpected currency ${famCurrency} in denom family for exchange ${exchangeBaseUrl}`);
      continue;
    }
    if (maxAmount != null && Amounts.cmp(fam.familyParams.value, maxAmount) > 0) {
      continue;
    }
    const fpSerial = fam.denominationFamilySerial;
    checkDbInvariant(typeof fpSerial === "number", "denominationFamilySerial");
    const denom = await tx.findDenominationByFamilyFromExpiry(fpSerial, dbNow, isCandidateWithdrawableDenomRec);
    if (denom) {
      relevantDenoms.push(denom);
    } else {
      logger37.warn(`no representative denom for family with serial=${fpSerial}`);
      logger37.info(`family details: ${j2s(fam)}`);
    }
  }
  relevantDenoms.sort((d1, d2) => Amounts.cmp(d2.value, d1.value));
  for (const denom of relevantDenoms) {
    if (acceptedMasterPub != null && denom.exchangeMasterPub != acceptedMasterPub) {
      throw Error(`invariant violation in withdrawal denom selection: denomination ${denom.denomPubHash} is signed by ${denom.exchangeMasterPub}, but was reached through a family of ${acceptedMasterPub}`);
    }
  }
  return relevantDenoms;
}
async function processPlanchetGenerate(wex, withdrawalGroup, coinIdx) {
  checkDbInvariant(withdrawalGroup.denomsSel !== void 0, "can't process uninitialized exchange");
  checkDbInvariant(withdrawalGroup.exchangeBaseUrl !== void 0, "can't get funding uri from uninitialized wg");
  const exchangeBaseUrl = withdrawalGroup.exchangeBaseUrl;
  let planchet = await wex.runWalletDbTx(async (tx) => {
    return tx.getPlanchetByGroupAndIndex(withdrawalGroup.withdrawalGroupId, coinIdx);
  });
  if (planchet) {
    return {};
  }
  let ci = 0;
  let isSkipped = false;
  let maybeDenomPubHash;
  for (let di = 0; di < withdrawalGroup.denomsSel.selectedDenoms.length; di++) {
    const d = withdrawalGroup.denomsSel.selectedDenoms[di];
    if (coinIdx >= ci && coinIdx < ci + d.count) {
      maybeDenomPubHash = d.denomPubHash;
      if (coinIdx >= ci + d.count - (d.skip ?? 0)) {
        isSkipped = true;
      }
      break;
    }
    ci += d.count;
  }
  if (isSkipped) {
    return {};
  }
  if (!maybeDenomPubHash) {
    throw Error("invariant violated");
  }
  const denomPubHash = maybeDenomPubHash;
  const denom = await wex.runWalletDbTx(async (tx) => {
    return getDenomInfo(wex, tx, {
      exchangeMasterPub: await getWithdrawalMasterPub(tx, exchangeBaseUrl),
      denomPubHash
    });
  });
  if (!denom) {
    return { badDenom: true };
  }
  let exchangeWithdrawValues;
  let csNonce;
  if (denom.denomPub.cipher === DenomKeyType.ClauseSchnorr) {
    const blindingSeed = deriveCsWithdrawBlindingSeed(decodeCrock(withdrawalGroup.secretSeed), coinIdx);
    const exchangeClient = walletExchangeClient(exchangeBaseUrl, wex);
    const prep = succeedOrThrow(await exchangeClient.postBlindingPrepare({
      body: {
        cipher: DenomKeyType.ClauseSchnorr,
        operation: "withdraw",
        seed: encodeCrock(blindingSeed),
        nks: [{ coin_offset: 0, denom_pub_hash: denomPubHash }]
      }
    }));
    checkProtocolInvariant(prep.r_pubs.length === 1, "exchange returned wrong number of Clause-Schnorr R-pairs");
    exchangeWithdrawValues = {
      cipher: DenomKeyType.ClauseSchnorr,
      r_pub_0: prep.r_pubs[0][0],
      r_pub_1: prep.r_pubs[0][1]
    };
    csNonce = encodeCrock(deriveCsNonce(blindingSeed, "withdraw", 0));
  }
  const r = await wex.cryptoApi.createPlanchet({
    denomPub: denom.denomPub,
    feeWithdraw: Amounts.parseOrThrow(denom.feeWithdraw),
    reservePriv: withdrawalGroup.reservePriv,
    reservePub: withdrawalGroup.reservePub,
    value: Amounts.parseOrThrow(denom.value),
    coinIndex: coinIdx,
    secretSeed: withdrawalGroup.secretSeed,
    restrictAge: withdrawalGroup.restrictAge,
    exchangeWithdrawValues,
    csNonce
  });
  const newPlanchet = {
    blindingKey: r.blindingKey,
    coinEv: r.coinEv,
    coinEvHash: r.coinEvHash,
    coinIdx,
    coinPriv: r.coinPriv,
    coinPub: r.coinPub,
    denomPubHash: r.denomPubHash,
    planchetStatus: PlanchetStatus.Pending,
    withdrawSig: r.withdrawSig,
    withdrawalGroupId: withdrawalGroup.withdrawalGroupId,
    ageCommitmentProof: r.ageCommitmentProof,
    exchangeWithdrawValues: r.exchangeWithdrawValues,
    lastError: void 0
  };
  await wex.runWalletDbTx(async (tx) => {
    const p2 = await tx.getPlanchetByGroupAndIndex(withdrawalGroup.withdrawalGroupId, coinIdx);
    if (p2) {
      planchet = p2;
      return;
    }
    await tx.upsertPlanchet(newPlanchet);
    planchet = newPlanchet;
  });
  return {};
}
function requireWithdrawalBatchCardinality(requestedCount, responseCount) {
  if (requestedCount === responseCount) {
    return;
  }
  throw TalerError.fromDetail(TalerErrorCode.WALLET_TRANSACTION_PROTOCOL_VIOLATION, {}, `exchange returned ${responseCount} withdrawal signatures for ${requestedCount} planchets`);
}
async function transitionKycRequired(wex, withdrawalGroup, legiRequiredResp, startIdx, requestCoinIdxs) {
  logger37.info("withdrawal requires KYC");
  const withdrawalGroupId = withdrawalGroup.withdrawalGroupId;
  const ctx = new WithdrawTransactionContext(wex, withdrawalGroupId);
  await ctx.wex.runWalletDbTx(async (tx) => {
    const [wg2, h] = await ctx.getRecordHandle(tx);
    if (!wg2) {
      return;
    }
    for (let i = startIdx; i < requestCoinIdxs.length; i++) {
      const planchet = await tx.getPlanchetByGroupAndIndex(withdrawalGroup.withdrawalGroupId, requestCoinIdxs[i]);
      if (!planchet) {
        continue;
      }
      planchet.planchetStatus = PlanchetStatus.KycRequired;
      await tx.upsertPlanchet(planchet);
    }
    switch (wg2.status) {
      case WithdrawalGroupStatus.PendingReady:
      case WithdrawalGroupStatus.PendingKyc:
        break;
      default:
        return;
    }
    wg2.kycPaytoHash = legiRequiredResp.h_payto;
    wg2.kycLastDeny = timestampPreciseToDb(TalerPreciseTimestamp.now());
    wg2.status = WithdrawalGroupStatus.PendingKyc;
    await h.update(wg2, "kyc-required");
  });
}
