async function transitionBankAborted(ctx) {
  logger37.info("bank aborted the withdrawal");
  return await ctx.wex.runWalletDbTx(async (tx) => {
    const [r, h] = await ctx.getRecordHandle(tx);
    if (!r) {
      return TaskRunResult.finished();
    }
    switch (r.status) {
      case WithdrawalGroupStatus.PendingRegisteringBank:
      case WithdrawalGroupStatus.PendingWaitConfirmBank:
        break;
      default:
        return TaskRunResult.backoff();
    }
    if (r.wgInfo.withdrawalType !== "bank-integrated") {
      throw Error("invariant failed");
    }
    const now = AbsoluteTime.toPreciseTimestamp(AbsoluteTime.now());
    r.wgInfo.bankInfo.timestampBankConfirmed = timestampPreciseToDb(now);
    r.status = WithdrawalGroupStatus.FailedBankAborted;
    await h.update(r, "bank-aborted");
    return TaskRunResult.progress();
  });
}
async function processBankRegisterReserve(wex, withdrawalGroupId) {
  const ctx = new WithdrawTransactionContext(wex, withdrawalGroupId);
  const withdrawalGroup = await getWithdrawalGroupRecordTx(wex, {
    withdrawalGroupId
  });
  if (!withdrawalGroup) {
    return TaskRunResult.finished();
  }
  if (withdrawalGroup.wgInfo.withdrawalType != "bank-integrated") {
    throw Error("wrong withdrawal record type");
  }
  const bankInfo = withdrawalGroup.wgInfo.bankInfo;
  if (!bankInfo) {
    throw Error("no bank info in bank-integrated withdrawal");
  }
  const uriResult = Result.orUndefined(TalerUris.parseRestricted(bankInfo.talerWithdrawUri, TalerUriAction.Withdraw));
  if (!uriResult) {
    throw Error(`can't parse withdrawal URL ${bankInfo.talerWithdrawUri}`);
  }
  const bankClient = walletBankIntegrationClient(uriResult.bankIntegrationApiBaseUrl, wex, getReserveRequestTimeout(withdrawalGroup));
  const statusResp = await bankClient.getWithdrawalOperationById(uriResult.withdrawalOperationId);
  switch (statusResp.case) {
    case "ok":
      break;
    case HttpStatusCode.NotFound:
      await transitionSimple(ctx, WithdrawalGroupStatus.PendingRegisteringBank, WithdrawalGroupStatus.FailedBankAborted, "wop-not-found");
      return TaskRunResult.progress();
    case HttpStatusCode.Conflict:
      await transitionSimple(ctx, WithdrawalGroupStatus.PendingRegisteringBank, WithdrawalGroupStatus.AbortedOtherWallet, "wop-conflict");
      return TaskRunResult.progress();
  }
  const status = statusResp.body;
  if (status.status === "aborted") {
    return transitionBankAborted(ctx);
  }
  const isFlexibleAmount = status.amount == null;
  return await registerReserveWithBank(wex, withdrawalGroupId, isFlexibleAmount);
}
