    logger41.trace(`peer debit contract terms amount: ${Amounts.stringify(req.partialContractTerms.amount)}`);
    logger41.trace(`peer debit deposit fees: ${Amounts.stringify(sel.totalDepositFees)}`);
    exchangeBaseUrl = coinSelRes.result.exchangeBaseUrl;
