async function handleInsufficientFunds(wex, proposalId, err2) {
  logger45.trace("handling insufficient funds, trying to re-select coins");
  const ctx = new PayMerchantTransactionContext(wex, proposalId);
  const proposal = await wex.runWalletDbTx(async (tx) => {
    return tx.getPurchase(proposalId);
  });
  if (!proposal) {
    return TaskRunResult.finished();
  }
  logger45.trace(`got error details: ${j2s(err2)}`);
  let brokenCoinPub;
  if (err2.code === TalerErrorCode.MERCHANT_POST_ORDERS_ID_PAY_INSUFFICIENT_FUNDS) {
    const exchangeReply = err2.exchange_reply;
    if (exchangeReply == null) {
      return recoverPayAfterStableFailure(ctx, {
        code: TalerErrorCode.WALLET_TRANSACTION_PROTOCOL_VIOLATION,
        message: "merchant claimed insufficient funds without an exchange reply"
      });
    }
    if (exchangeReply.code !== TalerErrorCode.EXCHANGE_GENERIC_INSUFFICIENT_FUNDS) {
      if (logger45.shouldLogTrace()) {
        logger45.trace("got exchange error reply (see below)");
        logger45.trace(j2s(exchangeReply));
      }
      return recoverPayAfterStableFailure(ctx, {
        code: TalerErrorCode.WALLET_TRANSACTION_PROTOCOL_VIOLATION,
        message: `unable to handle /pay exchange error response (${exchangeReply.code})`,
        exchangeReply
      });
    }
    brokenCoinPub = exchangeReply.coin_pub;
    logger45.trace(`excluding broken coin pub=${brokenCoinPub}`);
    if (!brokenCoinPub) {
      return recoverPayAfterStableFailure(ctx, {
        code: TalerErrorCode.WALLET_TRANSACTION_PROTOCOL_VIOLATION,
        message: "Exchange claimed bad coin, but coin was not used.",
        brokenCoinPub
      });
    }
    if (!proposal.payInfo?.payCoinSelection?.coinPubs.includes(brokenCoinPub)) {
      return recoverPayAfterStableFailure(ctx, {
        code: TalerErrorCode.WALLET_TRANSACTION_PROTOCOL_VIOLATION,
        message: "Exchange claimed a bad coin that was not used in payment.",
        brokenCoinPub
      });
    }
  } else if (err2.code === TalerErrorCode.MERCHANT_POST_ORDERS_ID_PAY_DENOMINATION_KEY_NOT_FOUND) {
    return recoverPayAfterStableFailure(ctx, {
      code: TalerErrorCode.WALLET_TRANSACTION_PROTOCOL_VIOLATION,
      message: "Denomination used in payment became invalid.",
      errorDetails: err2
    });
  } else {
    throw Error(`unsupported error code: ${err2.code}`);
  }
  if (!proposal.payInfo) {
    return TaskRunResult.backoff();
  }
  const repair = await wex.runWalletDbTx(async (tx) => {
    return reselectCoinsTx(tx, ctx, { excludeCoinPub: brokenCoinPub });
  });
  if (repair === "insufficient") {
    return recoverPayAfterStableFailure(ctx, err2);
  }
  if (repair === "gone") {
    return TaskRunResult.finished();
  }
  wex.ws.notify({
    type: NotificationType.BalanceChange,
    hintTransactionId: constructTransactionIdentifier({
      tag: TransactionType.Payment,
      proposalId
    })
  });
  return TaskRunResult.progress();
}
