var logger56 = new Logger("taldir.ts");
function createHAliasBuffer(aliasType, alias) {
  const encoder2 = new TextEncoder();
  const typeBytes = encoder2.encode(aliasType);
  const aliasBytes = encoder2.encode(alias);
  const payloadLength = typeBytes.length + aliasBytes.length;
  const totalBuffer = new Uint8Array(4 + payloadLength);
  const view = new DataView(totalBuffer.buffer);
  view.setUint32(0, payloadLength, false);
  totalBuffer.set(typeBytes, 4);
  totalBuffer.set(aliasBytes, 4 + typeBytes.length);
  return totalBuffer;
}
async function lookupAlias(wex, lookupRequest) {
  const taldirClient = new TalerDirectoryInstanceHttpClient(lookupRequest.taldirBaseUrl, wex.http);
  const resConf = await taldirClient.getConfig();
  switch (resConf.case) {
    case "ok": {
      let supported_types = resConf.body.alias_types;
      let typeFound = false;
      for (var t of supported_types) {
        if (t.name === lookupRequest.aliasType) {
          typeFound = true;
          break;
        }
      }
      if (!typeFound) {
        logger56.warn(`queried type not supported by directory`);
        return {};
      }
      break;
    }
    default:
      throw TalerError.fromDetail(TalerErrorCode.WALLET_ALIAS_REGISTRATION_FAILED, { directoryBaseUrl: lookupRequest.taldirBaseUrl }, "could not read the configuration of the directory service");
  }
  const hAliasBuffer = createHAliasBuffer(lookupRequest.aliasType, lookupRequest.alias);
  const hAlias = encodeCrock(sha512(hAliasBuffer));
  const res = await taldirClient.lookupAlias({ hAlias });
  switch (res.case) {
    case "ok":
      return {
        targetUri: res.body.target_uri
      };
    case HttpStatusCode.NotFound:
      return {};
    default:
      throw TalerError.fromDetail(TalerErrorCode.WALLET_ALIAS_REGISTRATION_FAILED, { directoryBaseUrl: lookupRequest.taldirBaseUrl }, "the directory service did not answer the alias lookup");
  }
}
async function registerAlias(wex, registerRequest) {
  const taldirClient = new TalerDirectoryInstanceHttpClient(registerRequest.taldirBaseUrl, wex.http);
  const res = await taldirClient.postRegistrationRequest({
    alias: registerRequest.alias,
    aliasType: registerRequest.aliasType,
    targetUri: registerRequest.targetUri,
    duration: registerRequest.duration
  });
  switch (res.case) {
    case "ok":
      return res.body;
    case HttpStatusCode.NotFound:
      throw TalerError.fromDetail(TalerErrorCode.WALLET_ALIAS_REGISTRATION_FAILED, { directoryBaseUrl: registerRequest.taldirBaseUrl }, `the directory service does not support the alias type "${registerRequest.aliasType}"`);
    default:
      throw TalerError.fromDetail(TalerErrorCode.WALLET_ALIAS_REGISTRATION_FAILED, { directoryBaseUrl: registerRequest.taldirBaseUrl }, "the directory service did not accept the registration request");
  }
}
async function completeAliasRegistration(wex, completionRequest) {
  const taldirClient = new TalerDirectoryInstanceHttpClient(completionRequest.taldirBaseUrl, wex.http);
  const encoder2 = new TextEncoder();
  const bytes1 = encoder2.encode(completionRequest.challenge);
  const bytes2 = encoder2.encode(completionRequest.targetUri);
  const combined = new Uint8Array(bytes1.length + bytes2.length);
  combined.set(bytes1, 0);
  combined.set(bytes2, bytes1.length);
  const solution = encodeCrock(sha512(combined));
  const hAliasBuffer = createHAliasBuffer(completionRequest.aliasType, completionRequest.alias);
  const hAlias = encodeCrock(sha512(hAliasBuffer));
  const res = await taldirClient.postRegistration({
    hAlias,
    solution
  });
  switch (res.case) {
    case "ok":
      return {};
    case HttpStatusCode.NotFound:
      throw TalerError.fromDetail(TalerErrorCode.WALLET_ALIAS_REGISTRATION_FAILED, { directoryBaseUrl: completionRequest.taldirBaseUrl }, "the directory service does not know this registration, it may have expired");
    case HttpStatusCode.Forbidden:
      throw TalerError.fromDetail(TalerErrorCode.GENERIC_FORBIDDEN, {}, "the directory service rejected the answer to the challenge");
    case HttpStatusCode.TooManyRequests:
      throw TalerError.fromDetail(TalerErrorCode.WALLET_ALIAS_REGISTRATION_FAILED, { directoryBaseUrl: completionRequest.taldirBaseUrl }, "too many attempts have been made to answer this registration challenge");
    default:
      throw TalerError.fromDetail(TalerErrorCode.WALLET_ALIAS_REGISTRATION_FAILED, { directoryBaseUrl: completionRequest.taldirBaseUrl }, "the directory service did not accept the registration");
  }
}

