    return candidates.filter((t) => isTokenValid(t)).filter((t) => t.kind === MerchantContractTokenKind.Subscription).filter((t) => !tokenIssuePubHash || t.tokenIssuePubHash === tokenIssuePubHash).filter((t) => !merchantBaseUrl || t.merchantBaseUrl === merchantBaseUrl);
