async function deleteDiscount(wex, tokenFamilyHash) {
  await wex.runWalletDbTx(async (tx) => {
    const tokens = (await tx.getTokensByFamilyHash(tokenFamilyHash)).filter((t) => t.kind === MerchantContractTokenKind.Discount).filter((t) => t.tokenFamilyHash === tokenFamilyHash);
    let inUse = false;
    for (const token of tokens) {
      if (isTokenInUse(token)) {
        inUse = true;
        break;
      }
    }
    if (inUse) {
      throw TalerError.fromDetail(TalerErrorCode.WALLET_TOKENS_IN_USE, { tokenFamilyHash }, "one or more tokens in this family are in use");
    }
    for (const token of tokens) {
      if (logger58.shouldLogTrace()) {
        logger58.trace(`deleting token in ${token.tokenIssuePubHash} token family`);
      }
      await tx.deleteToken(token.tokenUsePub);
    }
  });
  return {};
}
