async function handleAddExchange(wex, req) {
  let exchangeBaseUrl;
  if (req.exchangeBaseUrl) {
    logger59.warn("Deprecated request property: AddExchangeRequest.exchangeBaseUrl");
    exchangeBaseUrl = req.exchangeBaseUrl;
  } else if (req.uri) {
    if (req.uri.startsWith("taler")) {
      const p2 = Result.orUndefined(TalerUris.parse(req.uri));
      if (p2?.type !== TalerUriAction.AddExchange) {
        throw TalerError.fromDetail(TalerErrorCode.WALLET_TALER_URI_MALFORMED, { talerUri: req.uri, expectedAction: TalerUriAction.AddExchange }, "expected a taler://add-exchange/ URI");
      }
      exchangeBaseUrl = p2.exchangeBaseUrl;
    } else if (req.allowCompletion) {
      const completeRes = await handleCompleteExchangeBaseUrl(wex, {
        url: req.uri
      });
      if (completeRes.status != "ok") {
        throw TalerError.fromUncheckedDetail(completeRes.error);
      }
      exchangeBaseUrl = completeRes.completion;
    } else if (req.uri.startsWith("http")) {
      const canonUrl = canonicalizeBaseUrl(req.uri);
      if (req.uri != canonUrl) {
        throw TalerError.fromDetail(TalerErrorCode.WALLET_CORE_API_BAD_REQUEST, { parameter: "uri" }, `exchange base URL must be canonicalized (expected "${canonUrl}")`);
      }
      exchangeBaseUrl = req.uri;
    } else {
      throw TalerError.fromDetail(TalerErrorCode.WALLET_CORE_API_BAD_REQUEST, { parameter: "uri" }, "AddExchangeRequest.uri must be http(s):// or taler://");
    }
  } else {
    throw TalerError.fromDetail(TalerErrorCode.WALLET_CORE_API_BAD_REQUEST, { parameter: "uri" }, "AddExchangeRequest must either specify uri or exchangeBaseUrl");
  }
  return await runWithMaybeProgressContext(wex, "addExchange", req.progressToken, async () => {
    await fetchFreshExchangeWithRetryNow(wex, exchangeBaseUrl);
    if (!req.ephemeral) {
      await wex.runWalletDbTx(async (tx) => {
        await markExchangeAddedByUser(tx, exchangeBaseUrl);
      });
    }
    return {
      exchangeBaseUrl
    };
  });
}
