async function handleGetDepositWireTypes(wex, req) {
  const wtSet = /* @__PURE__ */ new Set();
  const wireTypeDetails = [];
  const talerBankHostnames = [];
  await wex.runWalletDbTx(async (tx) => {
    const exchanges = await tx.getExchanges();
    for (const exchange of exchanges) {
      const det = await getExchangeDetailsInTx(tx, exchange.baseUrl);
      if (!det) {
        continue;
      }
      if (req.currency !== void 0 && det.currency !== req.currency) {
        continue;
      }
      for (const acc of det.wireInfo.accounts) {
        let usable = true;
        for (const dr of acc.debit_restrictions) {
          if (dr.type === "deny") {
            usable = false;
            break;
          }
        }
        if (!usable) {
          continue;
        }
        const parsedPayto = Result.orUndefined(Paytos.fromString(acc.payto_uri));
        if (!parsedPayto) {
          continue;
        }
        let preferredEntryType = void 0;
        if (parsedPayto.targetType === PaytoType.IBAN) {
          if (det.currency === "HUF") {
            preferredEntryType = "bban";
          } else {
            preferredEntryType = "iban";
          }
        }
        if (parsedPayto.targetType === PaytoType.TalerBank) {
          if (!talerBankHostnames.includes(parsedPayto.host)) {
            talerBankHostnames.push(parsedPayto.host);
          }
        }
        if (!wtSet.has(parsedPayto.targetType)) {
          wtSet.add(parsedPayto.targetType);
          wireTypeDetails.push({
            paymentTargetType: parsedPayto.targetType,
            // Hostnames only apply to x-taler-bank.  The array is shared so
            // that it is possibly extended later by other exchanges with the
            // same wire type.
            talerBankHostnames: parsedPayto.targetType === PaytoType.TalerBank ? talerBankHostnames : void 0,
            preferredEntryType
          });
        }
      }
    }
  });
  return {
    wireTypeDetails
  };
}
