advancedCli.subcommand("dbMigrationResolve", "db-migration-resolve", {
  help: "Resolve an ambiguous mixed-schema wallet database offline."
}).requiredArgument("dbfile", clk.STRING, {
  help: "Wallet database file to resolve (the wallet must be stopped)."
}).requiredOption("keep", ["--keep"], clk.STRING, {
  help: "Authoritative schema: indexeddb or native."
}).requiredOption("backup", ["--backup"], clk.STRING, {
  help: "Nonexistent destination for the mandatory full SQLite backup."
}).flag("confirm", ["--confirm"], {
  help: "Confirm the explicit authority selection."
}).action(async (args) => {
  const cmd = args.dbMigrationResolve;
  if (!cmd.confirm) {
    throw new CliUsageError("db-migration-resolve requires --confirm");
  }
  if (cmd.keep !== "indexeddb" && cmd.keep !== "native") {
    throw new CliUsageError("--keep must be indexeddb or native");
  }
  await resolveWalletDbMigration(cmd.dbfile, cmd.keep, cmd.backup);
  console.log(
    `kept ${cmd.keep} as authoritative; full pre-resolution backup written to ${cmd.backup}`
  );
});
